package com.primehr.migration;import org.junit.jupiter.api.Test;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.Set;import static org.assertj.core.api.Assertions.assertThat;
class SuccessionV51MigrationParityTest{@Test void pairedMigrationsHaveMatchingDevelopmentAndMembershipStructures()throws Exception{String p=read("db/migration/postgresql/V51__succession_development_membership_lineage.sql").toLowerCase(),s=read("db/migration/sqlserver/V51__succession_development_membership_lineage.sql").toLowerCase();Set<String>names=Set.of("succession_development_plan","succession_development_source","succession_development_milestone","succession_development_review","succession_pool_membership_event","ix_succ_dev_plan_employee","ix_succ_dev_source_plan","ix_succ_dev_milestone_plan","ix_succ_dev_review_plan","ix_succ_membership_current");for(String m:Set.of(p,s)){assertThat(m).contains(names.toArray(String[]::new));assertThat(m).doesNotContain("auto_enroll","rsp_referral","promotion_action","appointment_action","payroll_action","drop table","delete from");}}private String read(String path)throws IOException{try(var in=getClass().getClassLoader().getResourceAsStream(path)){if(in==null)throw new IOException(path);return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}}
